"use client";

import * as React from "react";

import { GeoMesh, type MeshDevice, type MeshPath, type MeshRelay } from "@/components/lumesec/geo-mesh";

const device: MeshDevice = { id: "laptop", label: "Work laptop", location: "Amsterdam", lat: 52.37, lon: 4.9 };

const peers: MeshDevice[] = [
  { id: "build", label: "Build server", location: "Milan", lat: 45.46, lon: 9.19 },
  { id: "desktop", label: "Desktop", location: "Toronto", lat: 43.65, lon: -79.38 },
];

const relays: MeshRelay[] = [
  { id: "lhr", label: "London", lat: 51.51, lon: -0.13 },
  { id: "iad", label: "Ashburn", lat: 39.04, lon: -77.49 },
];

export function Example({ paths }: { paths: MeshPath[] }) {
  const [peer, setPeer] = React.useState<string | null>(null);
  return <GeoMesh device={device} peers={peers} relays={relays} paths={paths} value={peer} onValueChange={setPeer} />;
}
